@router.get("/builds/worker-pool/{task_id}/logs")
async def stream_build_logs(
    task_id: str,
    pool: RunnerPool = Depends(get_runner_pool),
    current_user: User = Depends(get_current_user)
):
    task_meta = pool.get_task_metadata(task_id)
    if not task_meta:
        raise HTTPException(status_code=404, detail="Build runner task not found")
    if task_meta.organization_id != current_user.organization_id and not current_user.is_platform_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized to stream logs for this build task")

    log_queue = pool.get_log_queue(task_id)
    async def log_generator():
        while True:
            chunk = await log_queue.get()
            if chunk is None:
                break
            yield f"data: {chunk}\n\n"

    return StreamingResponse(log_generator(), media_type="text/event-stream")
